nta.declaration:
// ============================= GLOBAL DECLARATIONS =============================
// Model parameters, shared state, and utility functions used by all templates.

// ------------------------------ Grid and timing ------------------------------

/*
 * Visible map and logical lane dimensions.
 * GRID_W and GRID_H are the visible Frogger grid.
 * LANE_W adds two off-screen cells to model the required re-entry delay of
 * moving objects after they leave the visible map.
 */
const int GRID_W = 18;
const int GRID_H = 13;
const int LANE_W = 20;

/*
 * Frogger spawn position.
 * Frogger is restored here after death, timeout, or successful home-bay arrival.
 */
const int FROG_SPAWN_X = 9;
const int FROG_SPAWN_Y = 0;

/*
 * Game timing and score bounds.
 * One Uppaal time unit represents 0.1 seconds.
 *
 * RESPAWN_TIME is 19 because the model also requires one additional
 * MOVE_COOLDOWN unit before Frogger can move again, giving 20 units in total
 * after a repositioning.
 *
 */
const int FROG_MAX_LIVES = 5;
const int MAX_SCORE = 300;

const int LEVEL_TIME = 30 * 10;           // 30 seconds * 10 ticks/seconds = 300 ticks
const int RESPAWN_TIME = 2 * 10;              // 2 seconds * 10 ticks/seconds = 20 ticks
const int MOVE_COOLDOWN = 1;                  // 1 tick

const int RIGHT = 1;
const int LEFT = -1;

// ------------------------------ Cell encoding ------------------------------

/*
 * Logical cell encoding used inside LANE_STRUCTURES.
 *
 */
const int S = 0; // safe/static street cell
const int W = 1; // water cell without floating support
const int V = 2; // vehicle-covered cell
const int L = 3; // log-supported cell
const int T = 4; // turtle-supported cell
const int D = 5; // diving-turtle-supported cell
const int X = 6; // wall between home bays
const int H = 7; // valid home-bay cell

/*
 * Diving-turtle phase durations.
 * Stable phases are emerged and submerged; transition phases are diving and
 * emerging.
 */
const int DIVING_TURTLE_TRANSITION_STATE_TIMER = 5;
const int DIVING_TURTLE_STABLE_STATE_TIMER = 10;

/*
 * Home-bay layout.
 * Each home bay occupies two cells and bays start every four x-coordinates:
 *   bay 0: x = 0, 1
 *   bay 1: x = 4, 5
 *   bay 2: x = 8, 9
 *   bay 3: x = 12, 13
 *   bay 4: x = 16, 17
 */
const int HOME_BAYS = 5;
const int HOME_BAY_SPACING = 4;

// ------------------------------ Scoring ------------------------------

/*
 * Score increments directly derived from the game rules.
 */
const int MOVE_UP_SCORE = 1;
const int HOME_BAY_SCORE = 5;
const int LEVEL_COMPLETE_SCORE = 100;

// ------------------------------ Bounded types ------------------------------

/*
 * Bounded integer types keep the symbolic state space finite.
 * PosX ranges over the logical lane width, including the two off-screen cells.
 */
typedef int[0, LANE_W - 1] PosX;
typedef int[0, GRID_H - 1] PosY;
typedef int[0, FROG_MAX_LIVES] Lives;
typedef int[0, MAX_SCORE] Score;
typedef int[-1, 1] Direction;
typedef int[0, 7] Cell;

// ------------------------------ Lane structure ------------------------------

/*
 * Initial logical content of each lane.
 *
 * The matrix is fixed: moving objects are not physically rewritten in the array.
 * Their motion is represented by the per-lane shift variable inside lane templates.
 *
 * Turtle groups are encoded as continuous support intervals, including the
 * water gaps between turtles of the same group. This abstracts the rule allowing
 * Frogger to stand between nearby turtles. Diving-turtle groups use D over the
 * whole group interval, so the whole support interval disappears while submerged.
 */
const Cell LANE_STRUCTURES[GRID_H][LANE_W] = {
    {S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S}, /// lane 0  - start lane
    {S,S,S,S,V,S,S,S,S,S,S,S,S,S,V,S,S,S,S,S}, // lane 1  - orange cars
    {S,S,V,S,S,S,S,S,S,S,S,V,S,S,S,S,S,S,S,S}, // lane 2  - bulldozers
    {S,S,S,V,S,S,S,S,V,S,S,S,S,V,S,S,S,V,S,S}, // lane 3  - green cars
    {S,S,V,S,S,S,S,S,S,S,V,S,S,S,S,S,S,S,S,S}, // lane 4  - purple cars
    {S,S,S,V,V,S,S,S,S,S,S,S,S,S,V,V,S,S,S,S}, // lane 5  - trucks
    {S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S,S}, /// lane 6  - safe median
    {W,W,W,W,W,T,T,T,T,T,W,W,W,D,D,D,D,D,W,W}, // lane 7  - turtles/diving turtles
    {W,W,W,W,W,W,W,L,L,L,W,L,L,L,W,L,L,L,W,W}, // lane 8  - logs
    {W,W,L,L,L,L,L,L,L,L,L,W,W,W,W,W,W,W,W,W}, // lane 9  - long log
    {W,T,T,T,W,W,W,W,W,D,D,D,W,W,W,W,W,W,W,W}, // lane 10 - turtles/diving turtles
    {W,L,L,L,L,L,W,W,W,L,L,L,L,L,W,W,W,W,W,W}, // lane 11 - logs
    {H,H,X,X,H,H,X,X,H,H,X,X,H,H,X,X,H,H,X,X}  /// lane 12 - home bays
};

/*
 * Per-lane movement periods.
 * Static lanes have speed 0 and are not instantiated.
 */
const int lane_speed_array[GRID_H] = {0, 3, 10, 5, 4, 7, 0, 6, 2, 7, 2, 2, 0};

/*
 * Per-lane movement directions.
 * RIGHT means increasing x; LEFT means decreasing x; 0 marks static lanes.
 */
const Direction lane_direction_array[GRID_H] = {
    0, LEFT, RIGHT, LEFT, RIGHT, LEFT, 0, RIGHT, RIGHT, LEFT, RIGHT, LEFT, 0
};

// ------------------------------ Global state ------------------------------

clock timer;

/*
 * Frogger state.
 * frog_x ranges over LANE_W, so Frogger can also be carried into the two
 * off-screen cells while riding a floating object.
 */
PosX frog_x = FROG_SPAWN_X;
PosY frog_y = FROG_SPAWN_Y;
Score score = 0;

/*
 * Shared dynamic flags.
 *
 * diving_turtles_are_submerged is global because all diving turtles start in
 * the same phase and follow the same deterministic cycle in this abstraction.
 *
 * home_bay_occupied stores whether each of the five home bays has already been
 * reached.
 */
bool diving_turtles_are_submerged = false;
bool home_bay_occupied[HOME_BAYS] = {false, false, false, false, false};

bool frog_on_diving_turtle = false;

// ------------------------------ Home-bay utilities ------------------------------


/*
 * Checks whether the home bay corresponding to the x-coordinate of Frogger
 * has already been reached and occupied.
 *
 * The home row is organized as five groups of four cells:
 *
 *   H H X X | H H X X | H H X X | H H X X | H H
 *
 * Therefore, each home bay starts every HOME_BAY_SPACING (in this case 4) cells:
 *
 *   bay 0 -> x = 0, 1
 *   bay 1 -> x = 4, 5
 *   bay 2 -> x = 8, 9
 *   bay 3 -> x = 12, 13
 *   bay 4 -> x = 16, 17
 *
 * Since both cells of the same home bay belong to the same block of size
 * HOME_BAY_SPACING, integer division maps them to the correct bay index:
 *
 *   0 / 4 = 0,  1 / 4 = 0
 *   4 / 4 = 1,  5 / 4 = 1
 *   8 / 4 = 2,  9 / 4 = 2
 *   12 / 4 = 3, 13 / 4 = 3
 *   16 / 4 = 4, 17 / 4 = 4
 *
 * Precondition:
 *   This function should only be called after verifying that the frog coordinates
 *   (frog_x,frog_y+1) are an H cell. Wall cells such as x = 2 or x = 3 would also map
 *   to bay 0, but they are not valid home bay cells.
 *
 * Returns:
 *   true if the home bay has already been occupied, false otherwise.
 */
bool is_current_home_bay_occupied() {
    return home_bay_occupied[frog_x / HOME_BAY_SPACING];
}

/*
 * Marks Frogger's current home bay as occupied.
 * The same /4 mapping used above converts the x-coordinate into the bay index.
 */
void set_current_home_bay_as_occupied() {
    home_bay_occupied[frog_x / HOME_BAY_SPACING] = true;
}

/*
 * Returns true exactly when all five home bays are occupied.
 */
bool all_home_bays_occupied() {
    int[0, HOME_BAYS] i;
    for (i = 0; i < HOME_BAYS; i++) {
        if (!home_bay_occupied[i]) return false;
    }
    return true;
}

// ------------------------------ Score utility ------------------------------

/*
 * Adds points to the score with saturation at MAX_SCORE.
 */
void add_score(int points) {
    score = (score + points > MAX_SCORE) ? MAX_SCORE : score + points;
}


// ------------------------------ Synchronisation channels ------------------------------

/*
 * Requests the death of Frogger.
 *
 * Sent by:
 *   - VehicleLane, when a vehicle overlaps Frogger.
 *   - FloatingLane, when Frogger is on unsafe water or on a submerged diving-turtle group.
 *
 * Received by:
 *   - Frog, which consumes the event and applies the death routine:
 *     one life is removed and Frogger is respawned.
 *
 * The channel is not broadcast because death is handled by a single controller:
 * only the Frog automaton must react to it.
 */
chan kill_frog;

/*
 * Announces that Frogger has completed a movement step.
 *
 * Sent by:
 *   - Frog, immediately after executing its move.
 *
 * Received by:
 *   - VehicleLane templates, to re-check whether the new Frogger position
 *     overlaps a vehicle.
 *   - FloatingLane templates, to re-check whether the new Frogger position
 *     is supported by a floating object or is unsafe.
 *
 * The channel is broadcast because several lane automata may need to observe
 * the same movement event, while Frogger must not wait for a specific receiver.
 */
broadcast chan frog_moved;

/*
 * Announces that diving turtles have entered the submerged phase.
 *
 * Sent by:
 *   - DivingTurtleCycle, when the global diving-turtle state becomes submerged.
 *
 * Received by:
 *   - FloatingLane templates containing diving turtles, to detect whether
 *     Frogger is currently standing on a submerged diving turtle.
 *
 * The channel is broadcast because the diving phase is global and potentially
 * relevant to more than one river lane.
 */
broadcast chan diving_turtles_submerged;

template.declaration:
// ============================== FROG DECLARATIONS ==============================
// Local timing and actions for the symbolic Frogger controller.

// ------------------------------ Local Variables --------------------------------
clock tick;

Lives lives = FROG_MAX_LIVES;

// ------------------------------ Local Utilities --------------------------------

/*
 * Restores Frogger to the spawn cell only.
 * Score, lives, lane shifts, and occupied home bays are intentionally unchanged.
 */
void reset() {
    frog_x = FROG_SPAWN_X;
    frog_y = FROG_SPAWN_Y;
    frog_on_diving_turtle = false;
    timer = 0;
}


// ------------------------------ Transition called functions --------------------------------

/*
 * Checks whether Frogger is on the home row.
 */
bool on_finish_lane() {
    return ((frog_y == GRID_H - 1));
}

/*
 * Checks whether the next upward move is allowed by the current abstraction.
 * Frogger cannot move outside of the map and when he is on the finish line he can
 * only jump into a free homebay.
 */
bool can_move() {
    return !(frog_x < 0 || frog_x >= GRID_W || LANE_STRUCTURES[frog_y+1][frog_x] == X || (LANE_STRUCTURES[frog_y+1][frog_x] == H && is_current_home_bay_occupied()));
}

/*
 * Performs the symbolic upward move and awards the movement point.
 * If frogger moves into a non-occupied home bay, it is set as reached
 */
void move() {
    frog_y = frog_y + 1;
    add_score(MOVE_UP_SCORE);
    if (on_finish_lane()) {
        set_current_home_bay_as_occupied();
        add_score(HOME_BAY_SCORE);
    }
}

// =========================== VEHICLE LANE DECLARATION =========================
// Shared template for road lanes. The lane identity is fixed by parameter lane_y.

// ------------------------------ Lane parameters ------------------------------

const Direction direction = lane_direction_array[lane_y];
const int speed = lane_speed_array[lane_y];
const PosY row = lane_y;

// ------------------------------ Local state ------------------------------

clock tick;
PosX shift = 0;

// ------------------------------ Lane movement ------------------------------

/*
 * Advances the logical lane offset by one cell.
 * The structure array stays fixed; shift represents motion modulo LANE_W.
 */
void move_lane() {
    shift = (LANE_W + shift + direction) % LANE_W;
}

// ------------------------------ Collision check ------------------------------

/*
 * Checks whether Frogger's visible x-position overlaps a vehicle in this lane.
 * The inverse shift maps Frogger's current coordinate back to the fixed lane
 * structure, where V is encoded as a true value and S as false.
 */
bool collision() {
    return LANE_STRUCTURES[row][(LANE_W + frog_x - shift) % LANE_W] == V;
}

// ========================== FLOATING LANE DECLARATION =========================
// Shared template for river lanes. The lane identity is fixed by parameter lane_y.

// ------------------------------ Lane parameters ------------------------------

const Direction direction = lane_direction_array[lane_y];
const int speed = lane_speed_array[lane_y];
const PosY row = lane_y;
// ------------------------------ Local state ------------------------------

clock tick;
PosX shift = 0;

// ------------------------------ Lane movement ------------------------------

/*
 * Advances the floating lane by one cell.
 * If Frogger is on this row, he is carried with the object before the lane
 * offset is updated. The modulo over LANE_W implements difficulty B wraparound,
 * including the two off-screen cells.
 */
void move_lane() {
    if (frog_y == row) {
        frog_x = (LANE_W + frog_x + direction) % LANE_W;
    }

    shift = (LANE_W + shift + direction) % LANE_W;
}

// ------------------------------ River safety check ------------------------------

/*
 * Checks whether Frogger is unsafe on this river lane.
 *
 * The inverse shift maps Frogger's current x-coordinate to the fixed support
 * structure. Water is encoded as 0 and causes drowning. Logs and regular turtle
 * support are encoded as 1 and are safe. Diving-turtle support is encoded as 2
 * and is safe except while the global diving phase is submerged.
 *
 * D cells may also cover the water gaps between diving turtles of the same
 * group: this intentionally abstracts the rule allowing Frogger to stand between
 * nearby turtles, while making the whole group unsafe when submerged.
 */
bool drowning() {
    Cell cell = LANE_STRUCTURES[row][(LANE_W + frog_x - shift) % LANE_W];
    return cell == W || (cell == D && diving_turtles_are_submerged);
}


/*
 * Checks whether frog is on a diving turtle. 
 */
void check_frog_on_diving_turtle() {
    Cell cell = LANE_STRUCTURES[row][(LANE_W + frog_x - shift) % LANE_W];
    frog_on_diving_turtle = (cell == D);
}

// ======================= DIVING TURTLE CYCLE DECLARATION ======================
// Deterministic global phase shared by all diving turtles.
//
// The template alternates emerged -> diving -> submerged -> emerging.
// Only the submerged phase disables D support in floating-lane safety checks.

clock tick;

nta.system:
// L1 is a static lane, according to our abstraction it isn't instantiated.

L1 = VehicleLane(1);
L2 = VehicleLane(2);
L3 = VehicleLane(3);
L4 = VehicleLane(4);
L5 = VehicleLane(5);

// L6 is a static lane, according to our abstraction it isn't instantiated.

L7 = FloatingLane(7);
L8 = FloatingLane(8);
L9 = FloatingLane(9);
L10 = FloatingLane(10);
L11 = FloatingLane(11);

// L12 is a static lane, according to our abstraction it isn't instantiated.

DTC = DivingTurtleCycle();

F = Frogger();

system L1, L2, L3, L4, L5, L7, L8, L9, L10, L11, DTC, F;
